    41	     * Unknown nodes can be replaced by concrete node types.
    42	     *
    43	     * @param Node $node The node to add to the graph
    44	     *
    45	     * @throws \InvalidArgumentException If a non-Unknown node with the same ID already exists
    46	     */
    47	    public function addNode(Node $node): void
