   203	     *
   204	     * Creates a new graph containing all nodes and edges from both graphs.
   205	     * Existing Unknown nodes can be replaced by concrete types from the other graph.
   206	     *
   207	     * @param Graph $other The graph to merge with this one
   208	     *
   209	     * @return Graph A new graph containing nodes and edges from both graphs
   210	     */
   211	    public function merge(Graph $other): Graph
   212	    {
   213	        $merged = new Graph();
   214	        $nodes = array_merge(
   215	            $this->nodes(),
   216	            $other->nodes()
   217	        );
   218	        $merged->addNodes($nodes);
   219	
   220	        $edges = array_merge(
   221	            array_flatten($this->adjacency),
   222	            array_flatten($other->adjacency),
   223	        );
