    10	 * This trait offers reusable validation logic for complex identifier checks.
    11	 * For simple validations (e.g., empty string checks), use assertions directly
    12	 * in the consuming class rather than this trait.
    13	 */
    14	trait IdentifierAssert
    15	{
    16	    /**
    17	     * Asserts that a value is a valid PHP identifier.
    18	     *
    19	     * Validates identifiers used for class names, method names, property names,
    20	     * function names, etc. according to PHP naming rules:
    21	     * - First character: a-z, A-Z, _, or 0x80-0xff (multibyte)
    22	     * - Subsequent characters: above characters plus 0-9
    23	     * - Must not be an empty string
    24	     *
    25	     * @param string                 $value       The value to validate as a PHP identifier
    26	     * @param null|string|\Throwable $description Optional description for assertion failure messages
    27	     */
    28	    protected static function assertIdentifier(string $value, string|\Throwable|null $description = null): void
    29	    {
    30	        assert(
    31	            $value !== '' && preg_match('/^[a-zA-Z_\x80-\xff][a-zA-Z0-9_\x80-\xff]*$/', $value) === 1,
    32	            $description
    33	        );
    34	    }
    35	
