    29	    public function traverse(Graph $graph, NodeId $symbol, callable $callback): void
    30	    {
    31	        /** @var array<string, true> */
    32	        $pathSet = [];
    33	
    34	        $traverseRecursive = function (NodeId $nodeId, int $depth) use ($graph, $callback, &$traverseRecursive, &$pathSet) {
    35	            $node = $graph->node($nodeId);
    36	            if ($node === null) {
    37	                return;
    38	            }
    39	
    40	            $key = $nodeId->toString();
    41	            $isRecursive = isset($pathSet[$key]);
    42	
    43	            if ($isRecursive) {
    44	                $callback($node, $depth);
    45	
    46	                return;
    47	            }
    48	
    49	            $pathSet[$key] = true;
    50	
    51	            $shouldContinue = $callback($node, $depth);
