 34	            throw new \RuntimeException('Unable to determine current working directory');
 35	        }
 36	        $containerFactory = new PhpStanContainerFactory($cwd);
 37	
 38	        // We need to create a configuration file that registers our collector.
 39	        // PHPStan ContainerFactory expects a list of config files.
 40	        // However, since we want to inject our own collector, we might need to do it dynamically
 41	        // or ensure the config loads it.
 42	        // Since we are running programmatically, we can try to add the collector to the container
 43	        // or use a temporary config file.
 44	
 45	        // A better approach for programmatic usage without a physical config file for the collector
 46	        // is to rely on PHPStan's ability to accept config files.
 47	        // But here we want to be self-contained.
 48	
 49	        // Let's try to create a container and then see if we can register the collector.
 50	        // PHPStan's container is compiled, so we can't easily add services at runtime unless we use a config file.
 51	
 52	        // Strategy: Create a temporary directory and put the neon file inside it.
 53	        // This avoids Nette DI trying to create a cache directory "inside" the config file path.
 54	
 55	        $tempDir = sys_get_temp_dir().'/peq-phpstan-'.uniqid();
 56	        mkdir($tempDir);
 57	        $tempConfig = $tempDir.'/phpstan.neon';
 58	
 59	        $content = [
 60	            'services' => [
 61	                [
 62	                    'class' => DependencyCollector::class,
 63	                    'tags' => ['phpstan.collector'],
 64	                ],
 65	                [
 66	                    'class' => InClassMethodCollector::class,
 67	                    'tags' => ['phpstan.collector'],
 68	                ],
 69	            ],
 70	            'parameters' => [
 71	                'customRulesetUsed' => true,
 72	                'level' => 0, // Collectors work at all levels; level 0 skips unused type-checking rules
 73	                'tmpDir' => $tempDir.'/tmp',
 74	            ],
 75	            'includes' => [],
 76	        ];
 77	
 78	        file_put_contents($tempConfig, $this->generateNeon($content));
 79	
 80	        try {
 81	            // create(string $tempDirectory, array $additionalConfigFiles, array $analysedPaths, ...)
 82	            return $containerFactory->create($tempDir, [$tempConfig], $files);
 83	        } catch (\Throwable $e) {
 84	            echo 'ContainerFactory error: '.$e->getMessage()."\n";
 85	
 86	            throw $e;
 87	        } finally {
 88	            // Recursive delete
 89	            $this->deleteDirectory($tempDir);
 90	        }
 91	    }
