 93	    private function deleteDirectory(string $dir): void
 94	    {
 95	        if (!file_exists($dir)) {
 96	            return;
 97	        }
 98	        $files = scandir($dir);
 99	        if ($files === false) {
100	            return;
101	        }
102	        $files = array_diff($files, ['.', '..']);
103	        foreach ($files as $file) {
104	            (is_dir("{$dir}/{$file}")) ? $this->deleteDirectory("{$dir}/{$file}") : unlink("{$dir}/{$file}");
