124	     * phar://phar://... paths that PHP cannot resolve. This method extracts the
125	     * bundled phpstan.phar to a temp directory and registers its autoloader.
126	     */
127	    private function ensurePhpStanAutoloader(): void
128	    {
129	        if (self::$phpStanAutoloaderInitialized || \Phar::running() === '') {
130	            return;
131	        }
132	        self::$phpStanAutoloaderInitialized = true;
133	
134	        $pharPhpstan = \Phar::running().'/vendor/phpstan/phpstan/phpstan.phar';
135	        if (!file_exists($pharPhpstan)) {
136	            throw new \RuntimeException('phpstan.phar not found inside the PHAR archive');
137	        }
138	
139	        $peqPhar = \Phar::running(false);
140	        $cacheKey = md5($peqPhar.'@'.filemtime($peqPhar));
141	        $cacheDir = sys_get_temp_dir().'/peq-phpstan-'.$cacheKey;
142	        $extractedPhar = $cacheDir.'/phpstan.phar';
143	
144	        if (!file_exists($extractedPhar)) {
145	            if (!is_dir($cacheDir)) {
146	                mkdir($cacheDir, 0o777, true);
147	            }
148	            copy($pharPhpstan, $extractedPhar);
149	        }
150	
151	        // Remove the broken PharAutoloader and register one from the extracted PHAR
152	        // @phpstan-ignore phpstanApi.classConstant
153	        if (class_exists(PharAutoloader::class, false)) {
154	            // @phpstan-ignore phpstanApi.classConstant
155	            spl_autoload_unregister([PharAutoloader::class, 'loadClass']);
156	        }
157	
158	        require_once 'phar://'.$extractedPhar.'/vendor/autoload.php';
159	    }
