/**
 * A generated graph together with the node it was grown from.
 *
 * Generating a symbol produces both a graph and the node at its root, and the
 * caller needs the node: it is the endpoint of the edge that attaches the symbol
 * to its parent. Returning only the graph would force the caller to look the node
 * back up and re-establish its type, which is how a generator ends up asserting
 * facts it already knew. Carrying the node keeps that type from being lost.
 *
 * @template TNode of Node
 */
final class GeneratedGraph
{
    /**
     * @param Graph $graph The generated graph
     * @param TNode $root  The node the generated graph was grown from
     */
    public function __construct(
        public readonly Graph $graph,
        public readonly Node $root,
    ) {}
}
