        $declared = self::declaredNode($node, $node->namespacedName->toString(), $meta);
        if ($declared === null) {
            return [];
        }

        return [
            $declared,
            ...AttributeProcessor::process($node->attrGroups, $declared, $scope, $meta),
            ...self::inheritance($node, $declared, $meta),
        ];
