    }

    #[DataProvider('providerEverySymbolItCanGenerate')]
    public function testEveryOperationRecordsItsRootInTheGraphItReturns(string $operation): void
    {
        $result = self::generate($operation);

        self::assertNotNull($result->graph->nodeNamed($result->root->id()->toString()));
    }

