    {
        $generator = SeededGenerators::graphs();
        $result = in_array($operation, ['constantGraph', 'enumCaseGraph', 'builtinGraph'], true)
            ? $generator->{$operation}(null)
            : $generator->{$operation}(null, 0);

        self::assertCount(1, $result->graph->nodes());
    }

