# move a docblock that landed between attributes and the declaration back above them
for p in pathlib.Path('tests').rglob('*.php'):
    lines = p.read_text().split('\n')
    out, i, changed = [], 0, False
    while i < len(lines):
        if re.match(r'^\s*#\[', lines[i]):
            # collect the attribute block
            attrs, j = [], i
            while j < len(lines) and re.match(r'^\s*#\[', lines[j]):
                attrs.append(lines[j]); j += 1
            if j < len(lines) and lines[j].strip() == '/**':
                doc, k = [], j
                while k < len(lines) and lines[k].strip() != '*/':
                    doc.append(lines[k]); k += 1
                if k < len(lines):
                    doc.append(lines[k]); k += 1
                    out.extend(doc); out.extend(attrs)
                    i = k; changed = True
                    continue
            out.extend(attrs); i = j
            continue
        out.append(lines[i]); i += 1
    if changed:
        p.write_text('\n'.join(out))
        print('reordered', p)
