namespace Tests\Fixture\Graph;

use App\Analyzer\Graph\IdentifierAssert;

/**
 * Exposes the identifier preconditions so a test can exercise them.
 *
 * The preconditions are written as assertions on a trait, which means they are only
 * reachable from a class that uses the trait. A test class may not use a trait, so
 * this fixture does, and hands each value straight back once the precondition has
 * accepted it — which is what lets a test assert that a name is admissible without
 * asserting that a violated precondition throws.
 */
final class IdentifierAssertions
{
    use IdentifierAssert;

    /**
     * Passes a value through the PHP identifier precondition.
     *
     * @param string $value The name to check
     *
     * @return string The same value, once the precondition has accepted it
     */
    public static function identifier(string $value): string
    {
        self::assertIdentifier($value);

        return $value;
    }

    /**
     * Passes a value through the PHP namespace precondition.
     *
     * @param string $value The namespace to check
     *
     * @return string The same value, once the precondition has accepted it
     */
    public static function namespaceName(string $value): string
    {
        self::assertNamespace($value);

        return $value;
    }
